[],"answer":"3","explanation":"13 = 10 + 3，所以十几就是十和 3。","verify":"13-10"},{"id":"hjm_g1a_u5_l2_q2","topicId":"hjm_g1a_u5_l2","difficulty":"basic","type":"choice","prompt":"下面哪个数是 1 个十和 6 个一组成的？","englishAudio":null,"options":["61","16","6"],"answer":"16","explanation":"1 个十和 6 个一组成 16。容易错的是写成 61，那是 6 个十和 1 个一。","verify":""},{"id":"hjm_g1a_u5_l2_q3","topicId":"hjm_g1a_u5_l2","difficulty":"hard","type":"numeric","prompt":"17 - 10 - 2 = ？","englishAudio":null,"options":[],"answer":"5","explanation":"17 - 10 = 7，7 - 2 = 5。","verify":"17-10-2=5"},{"id":"hjm_g1a_u5_l2_q4","topicId":"hjm_g1a_u5_l2","difficulty":"basic","type":"numeric","prompt":"12 - 10 + 5 = ？","englishAudio":null,"options":[],"answer":"7","explanation":"12 - 10 = 2，2 + 5 = 7。","verify":"12-10+5=7"},{"id":"hjm_g1a_u5_l2_q5","topicId":"hjm_g1a_u5_l2","difficulty":"hard","type":"numeric","prompt":"一个数是十和 8，这个数减去 4 是几？","englishAudio":null,"options":[],"answer":"14","explanation":"十和 8 就是 18，18-4=14。容易错的是直接答 8，忘了先把十和 8 合成 18。","verify":"18-4"},{"id":"hjm_g1a_u5_l2_q6","topicId":"hjm_g1a_u5_l2","difficulty":"basic","type":"numeric","prompt":"17 比 14 大几？","englishAudio":null,"options":[],"answer":"3","explanation":"17-14=3，大 3。","verify":"17-14"},{"id":"hjm_g1a_u5_l2_q7","topicId":"hjm_g1a_u5_l2","difficulty":"medium","type":"numeric","prompt":"15 比 12 大几？","englishAudio":null,"options":[],"answer":"3","explanation":"15 - 12 = 3。","verify":"15-12=3"},{"id":"hjm_g1a_u5_l2_q8","topicId":"hjm_g1a_u5_l2","difficulty":"medium","type":"numeric","prompt":"16 - 10 + 3 = ？","englishAudio":null,"options":[],"answer":"9","explanation":"16 - 10 = 6，6 + 3 = 9。","verify":"16-10+3=9"},{"id":"hjm_g1a_u5_l2_q9","topicId":"hjm_g1a_u5_l2","difficulty":"medium","type":"numeric","prompt":"17 - 13 = ？","englishAudio":null,"options":[],"answer":"4","explanation":"17 减去 13 等于 4。","verify":"17-13=4"},{"id":"hjm_g1a_u5_l3_q1","topicId":"hjm_g1a_u5_l3","difficulty":"basic","type":"numeric","prompt":"11、12、13、□、15，□里填几？","englishAudio":n