    public static func questionsForMathStage(_ stageId: Int) -> [CurriculumQuestion] {
        guard let stage = mathStages.first(where: { $0.id == stageId }) else { return [] }
        return allQuestions.filter { q in
            stage.topicPrefixes.contains(where: { q.topicId.hasPrefix($0) })
        }
    }

    /// 根据题目反查所属数学关卡（错题特训/全明星模式下用于发放对应甜点）
    public static func mathStageId(for q: CurriculumQuestion) -> Int? {
        mathStages.first(where: { st in st.topicPrefixes.contains(where: { q.topicId.hasPrefix($0) }) })?.id
    }

    /// 根据题目反查所属英语关卡
    public static func englishStageId(for q: CurriculumQuestion) -> Int? {
        englishStages.first(where: { st in st.topicPrefixes.contains(where: { q.topicId.hasPrefix($0) }) })?.id
    }

    /// 某个英语关卡可收集的闪卡（只统计真实存在于闪卡库中的单词）
    public static func flashcards(forEnglishStage stageId: Int) -> [EnglishFlashcard] {
        guard let stage = englishStages.first(where: { $0.id == stageId }) else { return [] }
        return englishFlashcards.filter { stage.topicWords.contains($0.word) }
    }

